/* contract: operations only, no state (cf. Linux *_operations structs) */
typedef struct file_ops {
    ssize_t (*read)(void *self, void *buf, size_t n);
    ssize_t (*write)(void *self, const void *buf, size_t n);
} file_ops;
void *open_file(const char *path, const file_ops *ops);  /* opaque handle */

ssize_t pump(void *src, const file_ops *sp, void *dst, const file_ops *dp) {
    char buf[4096];
    ssize_t n = sp->read(src, buf, sizeof buf);
    return n <= 0 ? n : dp->write(dst, buf, (size_t)n);
}
